	useEffect(() => {
		if (!open) return;
		const idx = defaultTabId
			? tabs.findIndex((t) => t.id === defaultTabId)
			: activeTab < tabs.length
				? activeTab
				: 0;
		setActiveTab(idx >= 0 ? idx : 0);
	}, [open, defaultTabId, tabs]);

	useEffect(() => {
		if (!open) return;
		const handleEscape = (e: KeyboardEvent) => {
			if (e.key === "Escape") onClose();
		};
