async function main() {
  const files = new Map<string, string>();
  const rootDir = process.cwd();

  for (const dir of SOURCE_DIRS) {
    try {
      for await (const filePath of walkDir(dir)) {
        const rel = relative(rootDir, filePath).replace(/\\/g, "/");
